data = collections.defaultdict(dict)
with open(VALUES_CSV) as f:
    r=csv.reader(f); next(r)
    for tsid, tstamp, val in r:
        data[tsid][tstamp]=val
def show(sid, lo, hi):
    d=dict(sorted(data[sid].items()))
    print(sid, "from", lo, "to", hi)
    prev=None
    for k,v in d.items():
        if lo<=k<=hi:
            if v!=prev:
                print("  ",k,v)
            prev=v
